Process.patch:
#N canvas 0 50 760 420 12;
#X text 20 14 A light sensor - an Arduino \, or a phone app - sends /sensor/light \, 0 to 1023 \, to Go.dot's OSC port. Steadied by go.smooth \, crossing 600 on the way up fires Lights up and on the way down Lights down.;
#X obj 20 100 r /sensor/light;
#X obj 20 140 go.smooth 0.8;
#X floatatom 200 140 6 0 0 0 - - - 0;
#X obj 20 180 go.edge 600 40;
#X msg 20 240 \; /godot/cmd/cue/fire PXSHN001;
#X msg 320 240 \; /godot/cmd/cue/fire PXDARK01;
#X connect 1 0 2 0;
#X connect 2 0 3 0;
#X connect 2 0 4 0;
#X connect 4 0 5 0;
#X connect 4 1 6 0;

#N canvas 0 50 760 420 12;
#X text 20 14 While the cue runs \, Ctrl+E on the canvas plays the patch: drag the slider. Its 0 to 127 goes to the desk as 0 to 1 \, at most twenty times a second.;
#X obj 20 100 hsl 160 18 0 127 0 0 empty /slider empty -2 -10 0 12 #fcfcfc #000000 #000000 0 1;
#X obj 20 150 r /slider;
#X obj 20 190 go.scale 0 127 0 1;
#X obj 20 230 go.ratelimit 50;
#X obj 20 270 s /desk/fader/1;
#X connect 2 0 3 0;
#X connect 3 0 4 0;
#X connect 4 0 5 0;
